"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["49397"],{47611(e,t,i){i.d(t,{Ay:()=>r,RM:()=>o});var s=i(74848),a=i(28453);let o=[];function n(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"the-dual-economic-structure-of-capitalist-social-formations",children:"The Dual Economic Structure of Capitalist Social Formations"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2008/7/3 15:42:51"}),"\n"]}),"\n",(0,s.jsx)("div",{style:{color:"#FF0000",fontWeight:"500",fontSize:"18px"},children:(0,s.jsx)(t.p,{children:"This ID's theories have always been consistent and unified. When this ID says there have never been any fellow travelers in economics circles, it's because those people's vision is far too narrow\u2014either bewitched by the pseudo-Marxist economics of Stalin or even Mao, or else bewitched by the tedious, dim-witted economics of the West. These people have never figured out, from a historical and realistic perspective, where the roots of these economic phenomena and patterns actually lie."})}),"\n",(0,s.jsx)("div",{style:{color:"#336600",fontWeight:"500",fontSize:"18px"},children:(0,s.jsx)(t.p,{children:"First, let's talk stocks. Today's low opening made yesterday's inverted T-pattern less than textbook, but the final result is similar. It's just that because today and yesterday form a containment relationship, the bottom fractal that could have been generated in standard fashion now needs to wait for tomorrow to form. The key levels currently are 2753, 2945, and 3483, which respectively constitute the critical positions for the short, medium, and long term. Before early next week, the first thing to confirm is the 2753-point level. Once this level fails to be effectively conquered, those with good short-term skills should take a short-term trade, because another probe to the bottom will be inevitable. Those who have proactively bought into the dip can also use this to lower their costs. Of course, if it can be effectively conquered, then a relatively large-level rebound is confirmed from here, and next we watch the 2945-point level\u2014beyond that is the gap area, and then comes 3483 points. All of this proceeds step by step and cannot skip stages."})}),"\n",(0,s.jsx)("div",{style:{color:"#CC0000",fontWeight:"500",fontSize:"20px"},children:(0,s.jsx)(t.p,{children:"Enough about stocks for now. Let's continue with the dual relationship. As for the triangular relationship, there will be opportunities to discuss that later\u2014the triangular relationship is bigger and more critical than the dual one."})}),"\n",(0,s.jsxs)("div",{style:{color:"#FF0000",fontWeight:"500",fontSize:"18px"},children:[(0,s.jsx)(t.p,{children:"In this ID's far more important post from N years ago, \"Currency Wars and the RMB Strategy,\" this ID had already\u2014in an unprecedented but essentially pure Marxist fashion\u2014identified the two real and historical types of capitalism: First, Western-style capitalism; Second, the nationalism-driven capitalism wearing the cloak of so-called socialism under the banner of anti-capitalism, a product of Lenin's deliberate misrepresentation\u2014and this type has without exception degenerated into Stalinist power-capitalism."}),(0,s.jsx)(t.p,{children:"The continued evolution and entanglement of these two types is the root and secret of all capitalist phenomena. All dual phenomena in capitalist societies\u2014whether state-owned versus private, government-run versus privately-run, planned versus market, and so on\u2014without exception originate from this."}),(0,s.jsx)(t.p,{children:"Note\u2014this has been repeatedly emphasized many times, but since so many people have been brainwashed by so-called common sense, it must be stated once more: in a purely Marxist perspective, it is impossible for a purely Marxist-sense socialist country to exist in the present era, because that would be a global event following the globalization of capitalism. Socialism cannot be established in a single country\u2014this is an immutable, necessary conclusion of Marxist theory. Once altered, it inevitably degenerates into Lenin-style anti-capitalist but essentially pure nationalist capitalism, which will ultimately degenerate into Stalinist power-capitalism."}),(0,s.jsx)(t.p,{children:"The dual economy, in fact, comprehensively exists in any capitalist country at any stage. However, in Western-style capitalist countries, one element of this duality exists as a latent structure. This latent structural existence serves two purposes: on one hand, the internal ruling need to fool the populace; on the other hand, it functions as a critical lethal weapon in national strategy and the process of globalization. (This is, of course, also this ID's unique discovery\u2014an exclusive theory. The specifics will be discussed in future posts about national strategy and globalization. There are far too many dim-witted theories in this area, and this ID will have to spend effort cleaning up the garbage. How boring.)"}),(0,s.jsx)(t.p,{children:"In Stalinist power-capitalism, the dual structure, under certain cultural, historical, and geographical conditions, can actually evolve into a powerful foundation and driving force for the economic development of a nationalist state. These conditions are extremely demanding\u2014for example, it must be a large country with deep and unique cultural traditions, and so on. Ordinary countries basically cannot possess all of these, yet China happens to fully satisfy all these conditions. This is truly the good fortune of the Chinese nation."}),(0,s.jsx)(t.p,{children:"Since too many people are influenced by Western garbage theories, it must be emphasized once more: the claim that a dual structure is a sign of backwardness is nothing more than narrow-minded drivel. The dual structure runs throughout every historical stage of capitalist society and will continue to exist until the demise of capitalism itself, merely evolving into different historical forms. If you can't even see this clearly, you deserve to be brainwashed by Westerners."}),(0,s.jsx)(t.p,{children:"N years ago, in this ID's collected writings, it was already clearly pointed out that the twentieth century was essentially the process of competition between Stalinist capitalism and Western capitalism. Ultimately, the latter defeated the former, and the former without exception evolved toward the latter."}),(0,s.jsx)(t.p,{children:"Pay attention\u2014this is the crux. But the game of capitalism, under historical and realistic objective conditions, cannot equally accommodate so many countries simultaneously existing in equal processes and stages. To put it bluntly: the Earth's current environment cannot simultaneously accommodate 200 countries all developed to America's level playing the Western capitalist game at the same time. What does this dictate?"}),(0,s.jsx)(t.p,{children:"This dictates that countries that entered the Western capitalist game first will inevitably guide the rules of this globalization game\u2014namely, a capital-based national slavery system founded on global division of labor. In plain language: America and these so-called advanced countries will create traps to turn those countries swarming in later\u2014seduced by the paradise of Western capitalism\u2014into new economic slaves in the new globalized order."}),(0,s.jsx)(t.p,{children:"Let me share with you another theorem, rigorously derived from this ID's economic theory and exclusive to this school: Reality always seeks the optimal structure amid the confrontation between environment and structure, and slavery or hierarchical structures are the optimal structures in resource-scarce environments."}),(0,s.jsx)(t.p,{children:"Those fools clamoring for democracy and equality don't realize that real-world capitalism is built on a true foundation of slavery or hierarchical structures, with internal social division of labor and external international division of labor forming the skin of this structure."}),(0,s.jsx)(t.p,{children:"The lie of a unitary economic structure is essentially the sweet bait used to lure latecomer nations into slavery."}),(0,s.jsx)(t.p,{children:"Alright, from here on I'll speak in plain language, because this is addressed to all Chinese people, and I hope everyone can understand. With the theoretical groundwork above, even a toenail could figure this out: if you want to resist this American-led process of capitalist enslavement and prevent China from falling into the trap of America's globalized slave structure, the only realistic choice is to use a different economic structure to counter this process."}),(0,s.jsx)(t.p,{children:"China's longstanding special dual structure has, in reality and in history, unconsciously yet fortunately and satisfactorily achieved this resistance\u2014this is the true secret behind China's economic miracle of the past thirty years."}),(0,s.jsx)(t.p,{children:"This ID's theories have always been consistent and require no revision. N years ago, this ID already mercilessly pointed out that capitalism is the shared karma of all humanity that cannot be escaped for the foreseeable future, and that globalization\u2014or in more precise but more brutal language, a capital-based national slavery system founded on global division of labor\u2014will also inevitably become the shared karma of humanity for the foreseeable future. So what is the only thing Chinese people can do?"}),(0,s.jsx)(t.p,{children:"This ID also clearly pointed out N years ago: the only thing Chinese people can do is resolutely refuse to be slaves and make others the slaves instead. China must take the lead in this globalization game. Since a slavery structure is unavoidable, the Chinese people must historically assume the role of the slave master\u2014this is the only correct choice of reality and history."}),(0,s.jsx)(t.p,{children:"Of course, some wretches can be quite thrilled to be slaves. Moreover, slaves come in different ranks. Some wretches first become America's sex slaves in various degrading ways, then come running back like pyramid-scheme peddlers to seduce 1.3 billion Chinese people into cheerfully becoming slaves so they can be slave overseers."}),(0,s.jsx)(t.p,{children:"The greatest risk to China's economy and China's national fortune is not anything else\u2014it's having these wretches seize control of China's cultural, economic, and political lifelines. China must not be degraded by wretches\u2014this is the most urgent matter at present."}),(0,s.jsx)(t.p,{children:"As long as China's dual economic structure continues to operate smoothly with its twin cores, China is invincible. Regulating China's economy is actually quite simple\u2014the core principle is this: maintain the twin-core operation of the dual economic structure. As long as this principle is upheld, all problems will be readily resolved."}),(0,s.jsx)(t.p,{children:"But this is far from enough. The relationship between politics and economics, questions of national strategy, and other deeper issues still need to be further explored. Regarding these questions, this ID will elaborate when in the mood. Today's post is already too long, so let's stop here."}),(0,s.jsx)(t.p,{children:"However, let me end with the following words that will probably make many people gasp: This ID's economic theory, like this ID's stock theory, can similarly encompass all previously existing economic theories, and it is likewise a purely axiomatic, geometry-like system. This ID once wrote a dozen or so posts, but didn't even finish the preface of the theory. Moreover, under present circumstances, the possibility of publication is essentially zero\u2014writing would be futile\u2014so there's no desire to write more."}),(0,s.jsx)(t.p,{children:"However, let me make one thing clear to everyone: this ID's economic theory requires only two premises: First, people need to eat; Second, everyone dies. If someone who violates these two premises ever appears, this ID won't need theories anymore. So if anyone discovers such a being that will widely replace current humans, please notify this ID immediately\u2014that would give this ID a legitimate excuse to be lazy, skip writing that thick book, and play more mahjong instead."}),(0,s.jsx)(t.p,{children:"Everyone, please do this ID that favor."})]})]})}function r(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(n,{...e})}):n(e)}},1220(e,t,i){i.r(t),i.d(t,{metadata:()=>s,default:()=>u,frontMatter:()=>r,contentTitle:()=>l,toc:()=>h,assets:()=>c});var s=JSON.parse('{"id":"economics/capitalismdualstructure","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/economics/capitalismdualstructure.md","sourceDirName":"economics","slug":"/economics/capitalismdualstructure","permalink":"/en/economics/capitalismdualstructure","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"capitalismdualstructure","title":"","hide_table_of_contents":true,"sidebar_label":"The Dual Economic Structure of Capitalist Social Formation (2008/7/3 15:42:51)"},"sidebar":"economicsSidebar","previous":{"title":"Dual Economic Structure, the Core Competitiveness of China\'s Economy. (2008/7/2 15:35:56)","permalink":"/en/economics/dualeconomicstructure"},"next":{"title":"What Is Dual Economic Structure (Latter Part Not Suitable for Children and Aliens) (2008/7/4 16:04:21)","permalink":"/en/economics/whatisdualstructure"}}'),a=i(74848),o=i(28453),n=i(47611);let r={id:"capitalismdualstructure",title:"",hide_table_of_contents:!0,sidebar_label:"The Dual Economic Structure of Capitalist Social Formation (2008/7/3 15:42:51)"},l,c={},h=[...n.RM];function d(e){return(0,a.jsx)(n.Ay,{})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,t,i){i.d(t,{R:()=>n,x:()=>r});var s=i(96540);let a={},o=s.createContext(a);function n(e){let t=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:n(e.components),s.createElement(o.Provider,{value:t},e.children)}}}]);